L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "\227\129\157\227\129\134\227\129\160\227\130\136\227\128\130\233\128\128\233\153\162\227\129\151\227\129\159\227\129\176\227\129\139\227\130\138\227\129\160\227\129\151\227\128\129\n\229\190\169\229\184\176\227\129\153\227\130\139\227\129\174\227\129\175\227\129\161\227\130\135\227\129\163\227\129\168\230\151\169\227\129\132\227\130\147\227\129\152\227\130\131\227\129\170\227\129\132\227\129\139\227\129\170\239\188\159"
L7_1.m_Talk_ENG = "S-she's right. I-isn\226\128\153t it too early for you to get back in the field; so soon after you were discharged from the hospital?"
