L7_1.m_Talk_SCN = "\230\152\175\239\188\140\230\152\175\229\149\138\227\128\130\229\136\154\229\136\154\229\135\186\233\153\162\229\176\177\229\155\158\230\157\165\228\186\134\239\188\140\228\188\154\228\184\141\228\188\154\230\151\169\228\186\134\231\130\185\239\188\159"
